    periodic_lookup: Dict[date, List[Tuple]] = defaultdict(list)
    for asset in plan.assets:
        series = price_map.get(asset.source_id)
        if series is None or series.empty:
            continue
        for rule in asset.rules:
            rule_start, rule_end = _rule_effective_window(rule, series, settings, sim_start, sim_end)
            if rule_start > rule_end:
                continue
            if rule.rule_type == "sip":
                for d in _generate_sip_dates(rule, rule_start, rule_end):
                    periodic_lookup[d].append((asset, rule))
            elif rule.rule_type == "swp":
                for d in _generate_swp_dates(rule, rule_start, rule_end):
                    periodic_lookup[d].append((asset, rule))
            elif rule.rule_type == "lumpsum" and not rule.trigger:
                ld = rule.lumpsum_date or rule_start
                if rule_start <= ld <= rule_end:
                    periodic_lookup[ld].append((asset, rule))
            elif rule.rule_type == "sell" and not rule.trigger:
                sd = rule.lumpsum_date or rule_start
                if rule_start <= sd <= rule_end:
                    periodic_lookup[sd].append((asset, rule))
            elif rule.rule_type == "switch" and not rule.trigger:
                sd = rule.switch_date or rule.lumpsum_date or rule_start
                if rule_start <= sd <= rule_end:
                    periodic_lookup[sd].append((asset, rule))

