def _build_attribution(
    attr_tracker: Dict,
    asset_state: Dict,
    price_map: Dict,
    sim_end: date,
) -> List[Dict]:
    out = []
    for (rule_type, asset_id), stats in attr_tracker.items():
        out.append({
            "rule_type": rule_type.upper(),
            "asset_id": asset_id,
            "fire_count": stats["fire_count"],
            "total_invested": round(stats["invested"], 2),
            "total_redeemed": round(stats["redeemed"], 2),
        })
    return out


